// Display orbits are deliberately stylized, not a numerical gravity simulation.
export function orbitPoint(center,radius,phase,speed,inclination,time){const a=phase+time*speed;return[center[0]+radius*Math.cos(a),center[1]+radius*Math.sin(a)*Math.sin(inclination),center[2]+radius*Math.sin(a)*Math.cos(inclination)]}
export function bodyPositions(data,regions,time){const result=new Map(),lookup=new Map(regions.map(r=>[r.id,r]));for(const d of data.filter(d=>d.kind!=='moon')){const r=lookup.get(d.region);if(d.kind==='star'){result.set(d.id,[r.center[0]+Math.sin(time*.018)*2,r.center[1]+Math.sin(time*.012)*1.5,r.center[2]]);continue}const o=d.orbit;result.set(d.id,orbitPoint(r.center,o.radius,o.phase,o.speed,o.inclination,time))}for(const d of data.filter(d=>d.kind==='moon')){const o=d.orbit;result.set(d.id,orbitPoint(result.get(d.parent)||lookup.get(d.region).center,o.radius,o.phase,o.speed,o.inclination,time))}return result}
export function encounterParameters(discovery,index){return Object.fromEntries(discovery.controls.map((c,i)=>{const steps=Math.round((c.max-c.min)/c.step);const step=(index*17+i*13+7)%(steps+1);return[c.id,Number((c.min+step*c.step).toFixed(6))]}))}
